//! System types: the recipes a system is generated by, as Open BIM Studio's building system types.
//!
//! A system is a face divided like a curtain wall: a grid of bays along it and rows up it, in a
//! pattern; members on the grid's lines (mullions and transoms, studs, mortar joints, seams); panels
//! in its bays (glass, insulation, bricks, boards). More layers can lie across the face, each a grid
//! of its own: the boards on either side of a timber frame. One generator makes them all; a type
//! says how. A floor or a ceiling is a system lying level.
//!
//! The starter types are Open BIM Studio's recipes for curtain walls, frames, timber frames,
//! masonry, cladding, hollow-core floors and a suspended ceiling, with generic names: no
//! manufacturer's system is claimed. The sizes are those recipes' authoring examples, not checked
//! structural, thermal or fire values.

use crate::material::Material;
use crate::{millimetres, Lang, LibraryError, MIN_THICKNESS};
use serde::{Deserialize, Serialize};

/// What a system is: the first word of its name, and the group it is listed under.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum SystemGroup {
    CurtainWall,
    Frame,
    TimberFrame,
    Masonry,
    Cladding,
    Floor,
    Ceiling,
}

impl SystemGroup {
    pub const ALL: [SystemGroup; 7] = [SystemGroup::CurtainWall, SystemGroup::Frame, SystemGroup::TimberFrame, SystemGroup::Masonry, SystemGroup::Cladding, SystemGroup::Floor, SystemGroup::Ceiling];

    /// Its name in `lang`, as a type's name starts.
    pub fn name(self, lang: Lang) -> &'static str {
        let [nl, en, de, fr] = match self {
            SystemGroup::CurtainWall => ["Vliesgevel", "Curtain wall", "Vorhangfassade", "Mur-rideau"],
            SystemGroup::Frame => ["Kozijn", "Frame", "Rahmen", "Châssis"],
            SystemGroup::TimberFrame => ["Houtskeletbouw", "Timber frame", "Holzrahmenbau", "Ossature bois"],
            SystemGroup::Masonry => ["Metselwerk", "Masonry", "Mauerwerk", "Maçonnerie"],
            SystemGroup::Cladding => ["Gevelbekleding", "Cladding", "Fassadenbekleidung", "Bardage"],
            SystemGroup::Floor => ["Vloer", "Floor", "Decke", "Plancher"],
            SystemGroup::Ceiling => ["Plafond", "Ceiling", "Unterdecke", "Faux plafond"],
        };
        match lang {
            Lang::Nl => nl,
            Lang::En => en,
            Lang::De => de,
            Lang::Fr => fr,
        }
    }

    /// Whether a type of it is named after its members (a curtain wall's mullions, a timber
    /// frame's studs) rather than its panels (bricks, boards, slabs, tiles).
    pub fn framed(self) -> bool {
        matches!(self, SystemGroup::CurtainWall | SystemGroup::Frame | SystemGroup::TimberFrame)
    }

    /// The IFC class of its type and its predefined type.
    pub fn ifc_type(self) -> (&'static str, &'static str) {
        match self {
            SystemGroup::CurtainWall => ("IfcCurtainWallType", "NOTDEFINED"),
            SystemGroup::Frame => ("IfcWindowType", "WINDOW"),
            SystemGroup::TimberFrame | SystemGroup::Masonry => ("IfcWallType", "STANDARD"),
            SystemGroup::Cladding => ("IfcCoveringType", "CLADDING"),
            SystemGroup::Floor => ("IfcSlabType", "FLOOR"),
            SystemGroup::Ceiling => ("IfcCoveringType", "CEILING"),
        }
    }
}

/// How a grid's rows lie: on one another, or every second row shifted half a bay (a stretcher
/// bond, staggered boards).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Pattern {
    #[default]
    Stack,
    RunningBond,
}

impl Pattern {
    /// Its name in `lang` in a type's name: masonry has a bond either way, other systems only say
    /// when they are staggered.
    pub fn name(self, group: SystemGroup, lang: Lang) -> Option<&'static str> {
        let [nl, en, de, fr] = match (self, group) {
            (Pattern::Stack, SystemGroup::Masonry) => ["stapelverband", "stack bond", "Stapelverband", "joints alignés"],
            (Pattern::RunningBond, SystemGroup::Masonry) => ["halfsteensverband", "stretcher bond", "Läuferverband", "appareil en panneresse"],
            (Pattern::RunningBond, _) => ["verspringend", "staggered", "versetzt", "décalé"],
            (Pattern::Stack, _) => return None,
        };
        Some(match lang {
            Lang::Nl => nl,
            Lang::En => en,
            Lang::De => de,
            Lang::Fr => fr,
        })
    }
}

/// How the members on a face's edges meet at its four corners: one stopping against the other, or
/// both cut on the diagonal.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Corner {
    #[default]
    Butt,
    Mitre,
}

fn is_butt(c: &Corner) -> bool {
    *c == Corner::Butt
}

/// A division of a face: bays `bay` wide along it and rows `row` high up it (or across it, when
/// it lies), centre to centre of the lines between them.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct Grid {
    pub bay: f64,
    pub row: f64,
    #[serde(default, skip_serializing_if = "is_stack")]
    pub pattern: Pattern,
}

fn is_stack(p: &Pattern) -> bool {
    *p == Pattern::Stack
}

impl Grid {
    pub fn new(bay: f64, row: f64, pattern: Pattern) -> Self {
        Self { bay, row, pattern }
    }
}

/// The members on a grid's lines: `width` in the face, `depth` across it, of `material`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Members {
    pub width: f64,
    pub depth: f64,
    pub material: String,
}

impl Members {
    pub fn new(width: f64, depth: f64, material: &str) -> Self {
        Self { width, depth, material: material.into() }
    }
}

/// The panels in a grid's bays: `thickness` of `material`, centred on the face.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Panels {
    pub material: String,
    pub thickness: f64,
}

impl Panels {
    pub fn new(material: &str, thickness: f64) -> Self {
        Self { material: material.into(), thickness }
    }
}

/// A layer across a system's face: its centre `offset` from the face (to the exterior positive, a
/// wall's right), a grid of its own, members on its lines or none (boards laid edge to edge), and
/// panels.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SystemLayer {
    pub offset: f64,
    pub grid: Grid,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub members: Option<Members>,
    pub panels: Panels,
}

/// A system type: its group, the grid of its face with its members and panels, the layers across
/// it, and, for a floor or a ceiling, how high above its level it lies.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SystemType {
    pub id: String,
    pub group: SystemGroup,
    pub grid: Grid,
    pub members: Members,
    pub panels: Panels,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub layers: Vec<SystemLayer>,
    /// How the members on its face's edges meet at the corners.
    #[serde(default, skip_serializing_if = "is_butt")]
    pub corners: Corner,
    /// A lying system's face, this high above its level (metres).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub lying: Option<f64>,
}

/// Whether a grid fits members `width` wide: positive bays and rows, wider than the members.
fn grid_fits(grid: &Grid, width: f64) -> bool {
    let positive = |v: f64| v.is_finite() && v >= MIN_THICKNESS;
    positive(grid.bay) && positive(grid.row) && grid.bay - width >= MIN_THICKNESS && grid.row - width >= MIN_THICKNESS
}

impl SystemType {
    /// Its members, panels and layers, from the face out: the face's own, then each layer's.
    pub fn faces(&self) -> impl Iterator<Item = (f64, &Grid, Option<&Members>, &Panels)> {
        std::iter::once((0.0, &self.grid, Some(&self.members), &self.panels)).chain(self.layers.iter().map(|l| (l.offset, &l.grid, l.members.as_ref(), &l.panels)))
    }

    /// How far it reaches across its face: from the back of its deepest part at the interior to
    /// the front of its deepest part at the exterior (metres), as `(interior, exterior)`, the
    /// interior negative.
    pub fn extent(&self) -> (f64, f64) {
        self.faces().fold((0.0_f64, 0.0_f64), |(lo, hi), (offset, _, members, panels)| {
            let half = members.map_or(0.0, |m| m.depth).max(panels.thickness) / 2.0;
            (lo.min(offset - half), hi.max(offset + half))
        })
    }

    /// Checks it against `materials`: an id; bays and rows wider than their members; members and
    /// panels at least 0.1 mm; every material known.
    pub fn check(&self, materials: &[Material]) -> Result<(), LibraryError> {
        if self.id.trim().is_empty() {
            return Err(LibraryError::NoKey);
        }
        let known = |key: &str| if materials.iter().any(|m| m.key == key) { Ok(()) } else { Err(LibraryError::UnknownMaterial(key.into())) };
        let thick = |v: f64| v.is_finite() && v >= MIN_THICKNESS;
        for (offset, grid, members, panels) in self.faces() {
            if !offset.is_finite() {
                return Err(LibraryError::NotPositive);
            }
            if let Some(m) = members {
                if !thick(m.width) || !thick(m.depth) {
                    return Err(LibraryError::NotPositive);
                }
                known(&m.material)?;
            }
            if !grid_fits(grid, members.map_or(0.0, |m| m.width)) {
                return Err(LibraryError::BadGrid);
            }
            if !thick(panels.thickness) {
                return Err(LibraryError::NotPositive);
            }
            known(&panels.material)?;
        }
        if self.lying.is_some_and(|h| !h.is_finite()) {
            return Err(LibraryError::NotPositive);
        }
        Ok(())
    }

    /// Its name by rule, in `lang`, never given by hand:
    ///
    /// - a curtain wall, frame or timber frame by its members: the group, their material (unless the
    ///   group's name says it), their size and their spacing ("Vliesgevel aluminium 50×150 h.o.h.
    ///   1500", "Houtskeletbouw 38×140 h.o.h. 600");
    /// - other systems by their panels: their material and thickness, the module of the grid and a
    ///   bond or a stagger ("Metselwerk 100 220×62.5 halfsteensverband", "Kanaalplaat 260
    ///   1200×6000").
    pub fn rule_name(&self, materials: &[Material], lang: Lang) -> String {
        let material = |key: &str| materials.iter().find(|m| m.key == key).map_or(key.to_string(), |m| m.name(lang).to_string());
        let mm = |v: f64| millimetres(v, lang);
        let mut name = if self.group.framed() {
            let group = self.group.name(lang);
            let made_of = material(&self.members.material);
            let spacing = match lang {
                Lang::Nl => "h.o.h.",
                Lang::En => "c/c",
                Lang::De => "Achsabstand",
                Lang::Fr => "entraxe",
            };
            let size = format!("{}×{} {spacing} {}", mm(self.members.width), mm(self.members.depth), mm(self.grid.bay));
            if group.to_lowercase().contains(&made_of.to_lowercase()) {
                format!("{group} {size}")
            } else {
                format!("{group} {made_of} {size}")
            }
        } else {
            let made_of = material(&self.panels.material);
            let mut chars = made_of.chars();
            let capitalised: String = chars.next().map(|c| c.to_uppercase().chain(chars).collect()).unwrap_or_default();
            format!("{capitalised} {} {}×{}", mm(self.panels.thickness), mm(self.grid.bay), mm(self.grid.row))
        };
        if let Some(pattern) = self.grid.pattern.name(self.group, lang) {
            name = format!("{name} {pattern}");
        }
        name
    }
}

/// The starter system types: Open BIM Studio's recipes for curtain walls, frames, timber frames,
/// masonry, sand-lime elements, cladding, hollow-core floors and a suspended ceiling. Glass is 24
/// mm, as there.
pub fn starter() -> Vec<SystemType> {
    use Pattern::*;
    use SystemGroup::*;
    let glass = || Panels::new("glass", 0.024);
    let upright = |id: &str, group, grid, members, panels| SystemType { id: id.into(), group, grid, members, panels, layers: Vec::new(), corners: Corner::Butt, lying: None };
    // aluminium and PVC frames are mitred at their corners
    let mitred = |t: SystemType| SystemType { corners: Corner::Mitre, ..t };
    // a timber frame: studs `depth` deep at 600 with mineral wool between them, OSB on the
    // exterior face and gypsum board on the interior one
    let timber_frame = |id: &str, depth: f64| {
        let boards = |offset: f64, material: &str, thickness: f64| SystemLayer { offset, grid: Grid::new(1.2, 3.0, Stack), members: None, panels: Panels::new(material, thickness) };
        SystemType {
            layers: vec![boards(depth / 2.0 + 0.009, "osb", 0.018), boards(-(depth / 2.0 + 0.00625), "gypsum-board", 0.0125)],
            ..upright(id, TimberFrame, Grid::new(0.6, 3.0, Stack), Members::new(0.038, depth, "timber"), Panels::new("mineral-wool", depth))
        }
    };
    let hollow_core = |depth: f64| SystemType {
        lying: Some(3.0),
        ..upright(&format!("system.hollow-core-{}", (depth * 1000.0).round()), Floor, Grid::new(1.2, 6.0, Stack), Members::new(0.02, depth, "grout"), Panels::new("hollow-core-concrete", depth))
    };
    let mut types = vec![
        upright("system.curtain-wall-aluminium-1500", CurtainWall, Grid::new(1.5, 1.8, Stack), Members::new(0.05, 0.15, "aluminium"), glass()),
        upright("system.curtain-wall-structural-glazing", CurtainWall, Grid::new(1.5, 3.0, Stack), Members::new(0.02, 0.18, "aluminium"), glass()),
        upright("system.curtain-wall-timber-aluminium-1200", CurtainWall, Grid::new(1.2, 1.5, Stack), Members::new(0.06, 0.16, "timber"), glass()),
        upright("system.frame-timber-67x114", Frame, Grid::new(0.9, 1.2, Stack), Members::new(0.067, 0.114, "timber"), glass()),
        mitred(upright("system.frame-aluminium-75", Frame, Grid::new(1.0, 1.4, Stack), Members::new(0.05, 0.075, "aluminium"), glass())),
        mitred(upright("system.frame-pvc-70", Frame, Grid::new(1.0, 1.4, Stack), Members::new(0.064, 0.07, "pvc"), glass())),
        timber_frame("system.timber-frame-140", 0.14),
        timber_frame("system.timber-frame-184", 0.184),
        // bricks as panels, the mortar as members set back 5 mm from either face
        upright("system.masonry-waal-stretcher", Masonry, Grid::new(0.22, 0.0625, RunningBond), Members::new(0.01, 0.09, "mortar"), Panels::new("brick", 0.1)),
        upright("system.masonry-dik-stretcher", Masonry, Grid::new(0.22, 0.075, RunningBond), Members::new(0.01, 0.09, "mortar"), Panels::new("brick", 0.1)),
        upright("system.masonry-waal-stack", Masonry, Grid::new(0.22, 0.0625, Stack), Members::new(0.01, 0.09, "mortar"), Panels::new("brick", 0.1)),
        upright("system.sand-lime-elements-100", Masonry, Grid::new(0.9, 0.6465, RunningBond), Members::new(0.003, 0.1, "glue"), Panels::new("sand-lime", 0.1)),
        upright("system.cladding-zinc-standing-seam-430", Cladding, Grid::new(0.43, 6.0, Stack), Members::new(0.006, 0.04, "zinc"), Panels::new("zinc", 0.0008)),
        upright("system.cladding-timber-boards-140", Cladding, Grid::new(4.0, 0.14, RunningBond), Members::new(0.004, 0.012, "timber"), Panels::new("timber-cladding", 0.018)),
        upright("system.cladding-hpl-1200x3000", Cladding, Grid::new(1.2, 3.0, Stack), Members::new(0.008, 0.004, "aluminium"), Panels::new("hpl", 0.008)),
    ];
    types.extend([0.15, 0.2, 0.26, 0.32, 0.4].map(hollow_core));
    types.push(SystemType { lying: Some(2.6), ..upright("system.ceiling-600x600", Ceiling, Grid::new(0.6, 0.6, Stack), Members::new(0.024, 0.038, "steel"), Panels::new("mineral-fibre", 0.015)) });
    types
}

#[cfg(test)]
mod tests {
    use super::*;

    fn materials() -> Vec<Material> {
        crate::material::starter()
    }

    #[test]
    fn the_starter_types_check_and_have_names_of_their_own() {
        let types = starter();
        assert_eq!(types.len(), 21);
        for t in &types {
            t.check(&materials()).unwrap_or_else(|e| panic!("{}: {e}", t.id));
        }
        for lang in Lang::ALL {
            let mut names: Vec<String> = types.iter().map(|t| t.rule_name(&materials(), lang)).collect();
            names.sort();
            names.dedup();
            assert_eq!(names.len(), types.len(), "{lang:?}: {names:?}");
        }
    }

    #[test]
    fn a_type_is_named_after_its_members_or_its_panels() {
        let types = starter();
        let name = |id: &str, lang| types.iter().find(|t| t.id == id).unwrap().rule_name(&materials(), lang);
        assert_eq!(name("system.curtain-wall-aluminium-1500", Lang::Nl), "Vliesgevel aluminium 50×150 h.o.h. 1500");
        assert_eq!(name("system.curtain-wall-aluminium-1500", Lang::En), "Curtain wall aluminium 50×150 c/c 1500");
        // the group's name says the material
        assert_eq!(name("system.timber-frame-140", Lang::Nl), "Houtskeletbouw 38×140 h.o.h. 600");
        assert_eq!(name("system.timber-frame-140", Lang::Fr), "Ossature bois 38×140 entraxe 600");
        assert_eq!(name("system.frame-pvc-70", Lang::De), "Rahmen PVC 64×70 Achsabstand 1000");
        assert_eq!(name("system.masonry-waal-stretcher", Lang::Nl), "Metselwerk 100 220×62.5 halfsteensverband");
        assert_eq!(name("system.masonry-waal-stack", Lang::En), "Brickwork 100 220×62.5 stack bond");
        assert_eq!(name("system.masonry-dik-stretcher", Lang::De), "Mauerwerk 100 220×75 Läuferverband");
        assert_eq!(name("system.cladding-timber-boards-140", Lang::En), "Timber cladding 18 4000×140 staggered");
        assert_eq!(name("system.hollow-core-260", Lang::Nl), "Kanaalplaat 260 1200×6000");
        assert_eq!(name("system.cladding-zinc-standing-seam-430", Lang::Fr), "Zinc 0,8 430×6000");
    }

    #[test]
    fn a_timber_frame_has_its_boards_on_its_faces() {
        let t = starter().into_iter().find(|t| t.id == "system.timber-frame-140").unwrap();
        // OSB 18 against the studs' exterior face, gypsum board 12.5 against their interior one
        let (interior, exterior) = t.extent();
        assert!((exterior - (0.07 + 0.018)).abs() < 1e-12 && (interior + (0.07 + 0.0125)).abs() < 1e-12, "{interior} {exterior}");
        assert_eq!(t.faces().count(), 3);
        assert!(t.layers.iter().all(|l| l.members.is_none()), "boards lie edge to edge");
    }

    #[test]
    fn a_type_that_does_not_make_a_system_is_refused() {
        let good = starter().into_iter().next().unwrap();
        let with = |f: &dyn Fn(&mut SystemType)| {
            let mut t = good.clone();
            f(&mut t);
            t.check(&materials())
        };
        assert_eq!(with(&|t| t.grid.bay = 0.04), Err(LibraryError::BadGrid), "a bay narrower than the members");
        assert_eq!(with(&|t| t.grid.row = 0.0), Err(LibraryError::BadGrid));
        assert_eq!(with(&|t| t.members.depth = 0.0), Err(LibraryError::NotPositive));
        assert_eq!(with(&|t| t.panels.thickness = f64::NAN), Err(LibraryError::NotPositive));
        assert_eq!(with(&|t| t.members.material = "unobtainium".into()), Err(LibraryError::UnknownMaterial("unobtainium".into())));
        assert_eq!(with(&|t| t.id = " ".into()), Err(LibraryError::NoKey));
    }

    #[test]
    fn a_type_reads_back_from_json_and_leaves_out_what_it_lacks() {
        for t in starter() {
            let text = serde_json::to_string(&t).unwrap();
            assert_eq!(serde_json::from_str::<SystemType>(&text).unwrap(), t);
        }
        let curtain = serde_json::to_value(&starter()[0]).unwrap();
        assert!(curtain.get("layers").is_none() && curtain.get("lying").is_none() && curtain.get("corners").is_none() && curtain["grid"].get("pattern").is_none(), "{curtain}");
        let aluminium = starter().into_iter().find(|t| t.id == "system.frame-aluminium-75").unwrap();
        assert_eq!(serde_json::to_value(&aluminium).unwrap()["corners"], "mitre");
    }
}
